package cn.iocoder.yudao.module.hrm.service.payroll;

import cn.iocoder.yudao.framework.common.util.json.JsonUtils;
import cn.iocoder.yudao.module.hrm.dal.dataobject.payroll.*;
import cn.iocoder.yudao.module.hrm.dal.mysql.payroll.*;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import java.util.stream.Collectors;
import static cn.iocoder.yudao.module.hrm.service.payroll.HrmPayrollGovernanceStore.*;

/** Only this projection leaves the server. Never return the stored complete snapshot to a client. */
@Service
@org.springframework.transaction.annotation.Transactional(rollbackFor=Exception.class,isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
@SuppressWarnings("unchecked")
public class HrmPayrollGovernanceProjectionService {
    public static final List<String> SHEETS=Arrays.asList("评审版本说明","功能需求清单","数据源清单","字段映射","问题与待办","范围与变更");
    @Resource private HrmPayrollGovernanceStore store;
    @Resource private HrmPayrollRequirementProjectMapper projects;
    @Resource private HrmPayrollRequirementAccessService access;
    @Resource private HrmPayrollGovernanceRootService roots;
    Map<String,Object> obj(Object o){return o instanceof Map?(Map<String,Object>)o:JsonUtils.parseObject(JsonUtils.toJsonString(o),Map.class);}
    List<Map<String,Object>> list(Object o){return o==null?new ArrayList<>():((List<?>)o).stream().map(this::obj).collect(Collectors.toList());}
    String text(Object o){return o==null?"":o instanceof String?(String)o:JsonUtils.toJsonString(o);}
    Map<String,Object> nodeData(Map<String,Object> n){return JsonUtils.parseObject(String.valueOf(n.get("dataJson")),Map.class);}
    boolean permitted(HrmPayrollRequirementProjectDO p,HrmPayrollRequirementDO r,Long actor,String action){return access.row(p,r,actor,"READ")&&access.row(p,r,actor,action);}
    boolean source(HrmPayrollRequirementProjectDO p,Map<String,Object> n,Long actor,String action){Map<String,Object>d=nodeData(n);return access.source(p,id(n.get("id")),text(d.get("module")),text(d.get("scopeJson")),actor,"READ")&&access.source(p,id(n.get("id")),text(d.get("module")),text(d.get("scopeJson")),actor,action);}
    boolean allVisible(Collection<?> ids,Set<Long> visible){return ids==null||ids.stream().allMatch(x->visible.contains(id(x)));}
    String name(Object id,Map<Long,String>names){return id==null?"":names.getOrDefault(HrmPayrollGovernanceStore.id(id),"当时未记录显示名");}
    Map<String,Object> ratio(long n,long d){return map("numerator",n,"denominator",d,"label",d==0?"暂无适用项（0/0）":n+"/"+d,"percent",d==0?null:java.math.BigDecimal.valueOf(n*100.0/d).setScale(2,java.math.RoundingMode.HALF_UP));}
    public Map<String,Object> project(Long project,Long releaseId,Long actor,String action,List<Long> filter){return access.withReadAuthorization(()->projectRead(project,releaseId,actor,action,filter));}
    private Map<String,Object> projectRead(Long project,Long releaseId,Long actor,String action,List<Long> filter){
        store.lock();
        HrmPayrollRequirementProjectDO p=projects.selectById(project);allowed(p!=null&&access.project(p,actor,"READ")&&access.project(p,actor,action));
        HrmPayrollGovernanceRecordDO release=store.record(releaseId,"RELEASE");allowed(Objects.equals(project,release.getProjectId()));Map<String,Object> releaseData=store.data(release),snapshot=obj(releaseData.get("snapshot"));
        Map<String,List<Map<String,Object>>> sheets=new LinkedHashMap<>();SHEETS.forEach(s->sheets.put(s,new ArrayList<>()));
        List<Map<String,Object>> allReq=list(snapshot.get("requirements")),nodes=list(snapshot.get("workbench"));Map<Long,HrmPayrollRequirementDO> reqs=new LinkedHashMap<>();
        for(Map<String,Object> data:allReq){HrmPayrollRequirementDO req=JsonUtils.parseObject(JsonUtils.toJsonString(data),HrmPayrollRequirementDO.class);if(permitted(p,req,actor,action)&&(filter==null||filter.contains(req.getId())))reqs.put(req.getId(),req);}
        Map<Long,Map<String,Object>> sources=new LinkedHashMap<>();for(Map<String,Object> n:nodes)if("SOURCE".equals(n.get("kind"))&&source(p,n,actor,action))sources.put(id(n.get("id")),n);
        Set<Long> permittedReqIds=new HashSet<>();for(Map<String,Object> data:allReq){HrmPayrollRequirementDO req=JsonUtils.parseObject(JsonUtils.toJsonString(data),HrmPayrollRequirementDO.class);if(permitted(p,req,actor,action))permittedReqIds.add(req.getId());}
        boolean people=access.full(p,actor,"PERSON_READ");boolean basis=roots.canPlatform(actor,"grant-read")&&roots.canPlatform(actor,"decision-read")&&people&&access.full(p,actor,"READ")&&access.full(p,actor,action)&&access.full(p,actor,"DECISION_READ")&&access.full(p,actor,"GRANT_READ")&&permittedReqIds.size()==allReq.size()&&sources.size()==nodes.stream().filter(n->"SOURCE".equals(n.get("kind"))).count();
        Set<Long> hiddenEdges=new HashSet<>(),issueVisible=new HashSet<>(),relationVisible=new HashSet<>(),relationExported=new HashSet<>();Map<Long,Map<String,Object>> relationNodes=new HashMap<>();
        for(Map<String,Object> n:nodes)if("RELATION".equals(n.get("kind"))){Map<String,Object>d=nodeData(n);relationNodes.put(id(n.get("id")),n);Long req=id(d.get("requirementId"));if(!reqs.containsKey(req))continue;if(sources.containsKey(id(d.get("sourceId")))){relationExported.add(id(n.get("id")));if(Boolean.TRUE.equals(d.get("active")))relationVisible.add(id(n.get("id")));}else hiddenEdges.add(req);}
        for(Map<String,Object> n:nodes)if("ISSUE".equals(n.get("kind"))){Map<String,Object>d=nodeData(n);Set<Long> affected=new LinkedHashSet<>();for(Object x:(List<?>)d.getOrDefault("requirementIds",Collections.emptyList()))affected.add(id(x));
            for(Object x:(List<?>)d.getOrDefault("relationIds",Collections.emptyList())){Map<String,Object> rel=relationNodes.get(id(x));if(rel!=null)affected.add(id(nodeData(rel).get("requirementId")));}
            Set<Long> issueSources=new HashSet<>();for(Object x:(List<?>)d.getOrDefault("sourceIds",Collections.emptyList()))issueSources.add(id(x));for(Map<String,Object> rel:relationNodes.values()){Map<String,Object>rd=nodeData(rel);if(issueSources.contains(id(rd.get("sourceId"))))affected.add(id(rd.get("requirementId")));}
            if(Boolean.TRUE.equals(d.get("wholeProject")))for(Map<String,Object> req:allReq)affected.add(id(req.get("id")));
            if(Collections.disjoint(affected,reqs.keySet()))continue;
            if(people&&allVisible(affected,reqs.keySet())&&allVisible((List<?>)d.getOrDefault("relationIds",Collections.emptyList()),relationExported)&&sources.keySet().containsAll(issueSources)&&(!Boolean.TRUE.equals(d.get("wholeProject"))||access.full(p,actor,"READ")&&access.full(p,actor,action)))issueVisible.add(id(n.get("id")));else for(Long req:affected)if(reqs.containsKey(req))hiddenEdges.add(req);
        }
        if(!people)hiddenEdges.addAll(reqs.keySet());
        Map<Long,String> names=new HashMap<>();for(Map<String,Object> u:list(snapshot.get("userFacts")))names.put(id(u.get("id")),text(u.get("nickname")));
        boolean restricted=!basis||!people||!access.full(p,actor,"READ")||!access.full(p,actor,action)||permittedReqIds.size()!=allReq.size()||!hiddenEdges.isEmpty();
        String label=restricted?"权限受限节选":filter!=null?"筛选节选":Boolean.TRUE.equals(releaseData.get("draft"))?(allReq.isEmpty()?"空草稿":"固定草稿快照"):"本期完整确认需求基线";
        if(filter!=null&&restricted)label+="（筛选）";String basisRef=basis?"SUMMARY-1":"受限发布依据";
        Set<Long> E=new LinkedHashSet<>(),I=new LinkedHashSet<>(),C=new LinkedHashSet<>(),T=new LinkedHashSet<>(),D=new LinkedHashSet<>();List<Map<String,Object>>L=new ArrayList<>();int exempt=0;Map<Long,String>placeholders=new HashMap<>();int ordinal=0;
        for(HrmPayrollRequirementDO req:reqs.values()){
            if(req.getScopeDecisionJson()!=null){Map<String,Object>sd=JsonUtils.parseObject(req.getScopeDecisionJson(),Map.class);if(sd.get("replacementId")!=null&&!reqs.containsKey(id(sd.get("replacementId"))))hiddenEdges.add(req.getId());}
            boolean redact=!basis||hiddenEdges.contains(req.getId());String reqRef="REQ-"+req.getId();if(hiddenEdges.contains(req.getId()))placeholders.put(req.getId(),"受限关联-"+(++ordinal));
            Map<String,Object> business=req.getBusinessContextJson()==null?Collections.emptyMap():JsonUtils.parseObject(req.getBusinessContextJson(),Map.class);
            sheets.get(SHEETS.get(1)).add(map("记录类型","REQUIREMENT","记录号",reqRef,"需求ID",text(req.getId()),"编号",req.getCode(),"模块",req.getModule(),"功能",redact?"关联依据受限，自由文本已裁剪":req.getDescription(),"业务场景与字段",redact?"受限":business,"功能评审",req.getStatus(),"当前签字有效（发布时）",Boolean.TRUE.equals(req.getCurrentConfirmationValid()),"范围决策",req.getScopeDecision(),"版本",req.getVersion(),"语义版本",req.getSemanticVersion(),"来源适用性",req.getSourceApplicability(),"不适用理由",redact?"受限":req.getApplicabilityReason(),"评审人ID",people?text(req.getReviewerId()):"受限","评审人当时姓名",people?name(req.getReviewerId(),names):"受限","确认时间",req.getConfirmedAt(),"验收条件",redact?"受限":req.getAcceptance(),"规则版本",redact?"受限":req.getRuleVersion(),"依据",redact?"受限":req.getEvidence(),"确认引用元组",redact?basisRef:req.getConfirmedTupleJson(),"发布依据关联",basisRef,"受限关联",placeholders.get(req.getId()),"优先级",req.getPriority(),"实施状态与证据",redact?"受限":req.getImplementationJson(),"协作历史",redact?"受限":req.getCollaborationJson()));
            sheets.get(SHEETS.get(5)).add(map("记录类型","SCOPE","记录号",reqRef,"需求ID",text(req.getId()),"编号",req.getCode(),"范围方式",req.getScopeMode(),"项目范围版本",req.getProjectScopeVersion(),"范围状态",req.getScopeState(),"范围正文",redact?"受限":req.getScopeJson(),"范围决策",req.getScopeDecision(),"排除及变更依据",redact?"受限":req.getScopeDecisionJson(),"页面上下文",redact?"受限":req.getBusinessContextJson(),"历史版本关联",redact?"受限":list(snapshot.get("requirementHistories")).stream().filter(h->Objects.equals(id(h.get("requirementId")),req.getId())).collect(Collectors.toList()),"发布依据关联",basisRef,"受限关联",placeholders.get(req.getId())));
            boolean removed="REMOVED".equals(req.getScopeDecision());if(!removed){E.add(req.getId());if("INCLUDED".equals(req.getScopeDecision()))I.add(req.getId());if("DEFERRED".equals(req.getScopeDecision()))T.add(req.getId());if("DISPUTED".equals(req.getStatus()))D.add(req.getId());if(Boolean.TRUE.equals(req.getCurrentConfirmationValid()))C.add(req.getId());}
            if("NOT_APPLICABLE".equals(req.getSourceApplicability())&&HrmPayrollWorkbenchService.validExemption(req.getApplicabilityReason())){if(!removed)exempt++;sheets.get(SHEETS.get(2)).add(map("记录类型","不适用声明","记录号","NA-"+req.getId(),"需求关联",reqRef,"需求ID",text(req.getId()),"理由",redact?"声明依据受限":req.getApplicabilityReason(),"确认人",people?text(req.getConfirmedBy()):"受限","确认人当时姓名",people?name(req.getConfirmedBy(),names):"受限","确认时间",req.getConfirmedAt(),"需求版本",req.getVersion(),"声明状态",req.getStatus(),"发布依据关联",basisRef));continue;}
            if(removed)continue;
            boolean found=false,hidden=false;for(Map<String,Object>fact:list(snapshot.get("relationFacts")))if(Objects.equals(id(fact.get("requirementId")),req.getId())){if(relationVisible.contains(id(fact.get("relationId")))){L.add(map("requirementId",req.getId(),"relationId",fact.get("relationId"),"available",fact.get("available")));found=true;}else hidden=true;}
            if(hidden||!found)L.add(map("requirementId",req.getId(),"relationId",null,"available",false));
        }
        for(Map<String,Object> n:sources.values()){Map<String,Object>d=nodeData(n);Map<String,Object> copy=new LinkedHashMap<>(d);if(!basis){copy=map("name",d.get("name"),"module",d.get("module"),"scopeJson",d.get("scopeJson"),"supply",d.get("supply"),"semanticVersion",d.get("semanticVersion"),"operationalVersion",d.get("operationalVersion"),"deliveryVersion",d.get("deliveryVersion"),"fields",list(d.get("fields")).stream().map(f->map("name",f.get("name"),"type",f.get("type"),"unit",f.get("unit"),"required",f.get("required"),"meaning","规格解释及依据受限")).collect(Collectors.toList()),"specification","规格解释及依据受限");}if(!people){copy.remove("ownerId");copy.remove("technicalContact");}sheets.get(SHEETS.get(2)).add(map("记录类型","SOURCE","记录号","SRC-"+n.get("id"),"来源ID",text(n.get("id")),"名称",d.get("name"),"负责人ID",people?text(d.get("ownerId")):"受限","负责人当时姓名",people?name(d.get("ownerId"),names):"受限","来源规格及供给",copy,"冻结历史及核验证据",basis&&filter==null?nodes.stream().filter(h->Arrays.asList("EVIDENCE","HISTORY").contains(h.get("kind"))&&Objects.equals(id(nodeData(h).get("objectId")),id(n.get("id")))).map(this::nodeData).collect(Collectors.toList()):"历史或依据未包含于当前节选","语义版本",d.get("semanticVersion"),"交付版本",d.get("deliveryVersion"),"发布依据关联",basisRef));}
        for(Long rid:relationExported){Map<String,Object>n=relationNodes.get(rid),d=nodeData(n);if(!reqs.containsKey(id(d.get("requirementId"))))continue;int field=0;for(Object raw:(List<?>)d.getOrDefault("fields",Collections.emptyList()))sheets.get(SHEETS.get(3)).add(map("记录类型","MAPPING","记录号","REL-"+rid+((++field)==1?"":"-F"+field),"关系ID",text(rid),"需求关联","REQ-"+d.get("requirementId"),"来源关联","SRC-"+d.get("sourceId"),"关系当前生效",d.get("active"),"映射版本",d.get("mappingVersion"),"字段映射及异常规则",basis?raw:map("pageField",obj(raw).get("pageField"),"sourceField",obj(raw).get("sourceField"),"type",obj(raw).get("type"),"unit",obj(raw).get("unit"),"required",obj(raw).get("required"),"transform","转换和异常规则依据受限"),"质量消费规则",basis?d.get("consumptionRule"):"受限","冻结语义质量及变更证据",basis&&filter==null?nodes.stream().filter(h->Arrays.asList("EVIDENCE","HISTORY").contains(h.get("kind"))&&Objects.equals(id(nodeData(h).get("objectId")),rid)).map(this::nodeData).collect(Collectors.toList()):"依据未包含于当前节选","发布依据关联",basisRef));}
        for(Map.Entry<Long,String> hidden:placeholders.entrySet()){
            Map<String,Object>placeholder=map("记录类型","受限关联","记录号",hidden.getValue(),"需求关联","REQ-"+hidden.getKey(),"说明","关联内容受限");sheets.get(SHEETS.get(2)).add(placeholder);sheets.get(SHEETS.get(3)).add(map("记录类型","受限关联","记录号",hidden.getValue(),"需求关联","REQ-"+hidden.getKey(),"来源关联",hidden.getValue(),"说明","关联内容受限"));sheets.get(SHEETS.get(4)).add(placeholder);
        }
        long unresolved=0,overdue=0;
        for(Map<String,Object> n:nodes)if(issueVisible.contains(id(n.get("id")))){Map<String,Object>d=nodeData(n);if(!"CLOSED".equals(d.get("state"))){unresolved++;if(java.time.LocalDate.parse(text(releaseData.get("createdAt")).substring(0,10)).isAfter(java.time.LocalDate.parse(text(d.get("dueDate")))))overdue++;}sheets.get(SHEETS.get(4)).add(map("记录类型","ISSUE","记录号","ISSUE-"+n.get("id"),"问题ID",text(n.get("id")),"处理及复核",basis?d:map("state",d.get("state"),"category",d.get("category"),"说明","自由文本依据受限"),"发布依据关联",basisRef));}
        for(Map<String,Object> n:nodes)if(Arrays.asList("TODO","PROPOSAL").contains(n.get("kind"))&&basis&&filter==null){Map<String,Object>d=nodeData(n);Long target=id(d.get("objectId"));if(sources.containsKey(target)||relationExported.contains(target)||issueVisible.contains(target))sheets.get(SHEETS.get(4)).add(map("记录类型",n.get("kind"),"记录号",n.get("kind")+"-"+n.get("id"),"对象关联",sources.containsKey(target)?"SRC-"+target:relationExported.contains(target)?"REL-"+target:"ISSUE-"+target,"待办及建议",d));}
        long ready=L.stream().filter(x->Boolean.TRUE.equals(x.get("available"))).count(),includedReady=L.stream().filter(x->I.contains(id(x.get("requirementId")))&&Boolean.TRUE.equals(x.get("available"))).count(),includedL=L.stream().filter(x->I.contains(id(x.get("requirementId")))).count();Set<Long>IC=new HashSet<>(I);IC.retainAll(C);
        Set<Long> consumedSources=new HashSet<>();for(Map<String,Object> fact:list(snapshot.get("relationFacts")))if(E.contains(id(fact.get("requirementId")))&&relationVisible.contains(id(fact.get("relationId"))))consumedSources.add(id(fact.get("sourceId")));
        Map<String,Object>stats=map("counts",map("U",reqs.size(),"E",E.size(),"I",I.size(),"C",C.size(),"T",T.size(),"D",D.size()),"confirmation",ratio(C.size(),E.size()),"scopeDisposition",ratio(I.size()+T.size(),E.size()),"includedConfirmation",ratio(IC.size(),I.size()),"readiness",ratio(ready,L.size()),"includedReadiness",ratio(includedReady,includedL),"sourceCount",consumedSources.size(),"exempt",exempt,"unresolvedIssues",unresolved,"overdueIssues",overdue,"L",L);
        sheets.get(SHEETS.get(0)).add(map("记录类型","SUMMARY","记录号","SUMMARY-1","项目ID",text(project),"项目当时名称",obj(snapshot.get("project")).get("name"),"项目范围版本",obj(snapshot.get("project")).get("projectScopeVersion"),"发布ID",text(releaseId),"发布版本",releaseData.get("version"),"完整性",label,"合成或正式",releaseData.get("mode"),"发布时刻",releaseData.get("createdAt"),"发布说明",basis?releaseData.get("reason"):"受限","统计",stats,"筛选",filter==null?"无":"按可见需求筛选","发布依据关联",basisRef,"用途","需求规格评审；不代表数据可投产"));
        if(basis){Map<String,Object>gate=obj(snapshot.get("gate"));Set<Long> usedDecisionIds=list(gate.get("decisions")).stream().map(d->id(d.get("recordId"))).collect(Collectors.toSet());for(Map<String,Object>raw:list(snapshot.containsKey("decisionVersions")?snapshot.get("decisionVersions"):gate.get("decisions"))){Map<String,Object>d=obj(raw.get("decision"));String ref="DEC-"+raw.get("recordId");sheets.get(SHEETS.get(0)).add(map("记录类型","DECISION","记录号",ref,"决议ID",d.get("decisionId"),"决议版本",d.get("decisionVersion"),"本次发布使用",usedDecisionIds.contains(id(raw.get("recordId"))),"条款及批准事实",d,"发布时状态",raw.get("lifecycleAtAction"),"授权关联","APPROVAL-GRANT-"+raw.get("recordId")));sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","APPROVAL-GRANT-"+raw.get("recordId"),"关联决议",ref,"当时批准授权闭包",d.get("approvalAuthority")));}sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","GRANT-PUBLISH","当时发布授权闭包",releaseData.get("publicationAuthority")));}
        if(basis){for(Map<String,Object> root:list(snapshot.get("controlledRoots")))sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","ROOT-"+root.get("id"),"授权根版本",root.get("version"),"授权根受控正文与签署",nodeData(root)));for(Map<String,Object> a:list(snapshot.get("controlledAnchors")))sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","ANCHOR-"+a.get("id"),"独立登记材料受控副本",nodeData(a)));for(Map<String,Object> g:list(snapshot.get("projectGrants")))sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","GRANT-"+g.get("id"),"授权事实",g,"授权根关联",g.get("rootRecordId")==null?"历史技术访问授权，无正式根":("ROOT-"+g.get("rootRecordId"))));if(filter==null)sheets.get(SHEETS.get(0)).add(map("记录类型","SUMMARY","记录号","PROJECT-HISTORY","项目范围及成员变更历史",snapshot.get("projectEvents")));}
        else sheets.get(SHEETS.get(0)).add(map("记录类型","GRANT","记录号","受限发布依据","说明","发布依据内容受限"));
        return map("releaseId",releaseId,"label",label,"restricted",restricted,"statistics",stats,"sheets",sheets);
    }
}
